// MPU-6050: raw I2C reads, no library
#include <Wire.h>

const int MPU = 0x68;   // AD0 low: address 0x68
int16_t ax, ay, az, gx;

void wake() {
  Wire.beginTransmission(MPU);
  Wire.write(0x6B);     // PWR_MGMT_1: write 0 to wake the chip (it powers up asleep)
  Wire.write(0);
  Wire.endTransmission();
}

void readImu() {
  Wire.beginTransmission(MPU);
  Wire.write(0x3B);     // ACCEL_XOUT_H: 14 bytes from here are accel X, Y, Z, temperature, gyro X, Y, Z
  Wire.endTransmission(false);
  Wire.requestFrom(MPU, 14);
  ax = Wire.read() << 8 | Wire.read();
  ay = Wire.read() << 8 | Wire.read();
  az = Wire.read() << 8 | Wire.read();
  Wire.read(); Wire.read();   // the temperature: skipped
  gx = Wire.read() << 8 | Wire.read();
  Wire.read(); Wire.read(); Wire.read(); Wire.read();
}

void setup() {
  Serial.begin(9600);
  Wire.begin();
  // no wake(): the chip stays asleep and every register reads 0
  Serial.println("mpu6050: reading without waking it");
}

void loop() {
  readImu();
  Serial.print("ax ");
  Serial.print(ax / 16384.0, 2);   // 16384 counts = 1 g at ±2 g
  Serial.print(" ay ");
  Serial.print(ay / 16384.0, 2);
  Serial.print(" az ");
  Serial.print(az / 16384.0, 2);
  Serial.print(" g | gx ");
  Serial.print(gx / 131.0, 1);     // 131 counts = 1 °/s at ±250 °/s
  Serial.println(" deg/s");
  delay(1000);
}

