const int BUZZER = 8;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  wake();
  pinMode(13, OUTPUT);
  Serial.println("tilt alarm: beeps past 20 deg");
}

void loop() {
  readImu();
  float roll = atan2(ay, az) * 180.0 / PI;   // roll about X: how much of gravity has moved from Z to Y
  bool alarm = abs(roll) > 20;
  digitalWrite(13, alarm ? HIGH : LOW);
  if (alarm) tone(BUZZER, 2000); else noTone(BUZZER);   // a 2 kHz tone on the buzzer while tipped too far
  if (millis() - lastPrint >= 1000) {
    lastPrint = millis();
    Serial.print("roll ");
    Serial.print(roll, 0);
    Serial.print(" deg");
    if (abs(roll) > 20) Serial.print(" ALARM");
    Serial.println();
  }
  delay(100);
}
